sp_widget.client_script:
api.controller = function($scope, $timeout, $element) {
  var c = this;

  // Attendre qu'Angular ait insere le template dans la page
  $timeout(function() {

    var faq = $element[0].querySelector('.faq');
    if (!faq) {
      return;
    }

    // Ajouter la classe is-visible quand la FAQ entre dans l'ecran
    var observateur = new IntersectionObserver(function(entrees) {
      for (var i = 0; i < entrees.length; i++) {
        if (entrees[i].isIntersecting) {
          entrees[i].target.className += ' is-visible';
          observateur.unobserve(entrees[i].target);
        }
      }
    }, { threshold: 0.2 });

    observateur.observe(faq);

    // Arreter l'observation si le widget est retire de la page
    $scope.$on('$destroy', function() {
      observateur.disconnect();
    });

  }, 0);
};

sp_widget.css:
/* ============================================================
   PORTAIL HABITAT — PAGE D'ACCUEIL
   Sommaire :
     1. Conteneur
     2. Fil d'Ariane
     3. Hero
     4. Bloc simulateur
     5. Actualités
     6. FAQ
     7. Informations pratiques
     8. Divers
   ============================================================ */


/* ============================================================
   1. CONTENEUR
   ============================================================ */
   .accueil-familles {
    font-family: 'Marianne', Arial, sans-serif;
    color: #161616;
    max-width: 1200px;
    margin: 0 auto;
    padding: 24px 16px 0;
    background-color: #ffffff;
  }
  
  /* On ne cible jamais * ni body : tout reste dans le widget */
  .accueil-familles * {
    box-sizing: border-box;
  }
  
  
  /* ============================================================
     2. FIL D'ARIANE
     ============================================================ */
  .breadcrumb {
    margin: 0 0 24px;
    padding: 12px 16px;
    background-color: #F6F6F6;
    font-size: 14px;
  }
  
  .breadcrumb ol {
    list-style: none;
    display: flex;
    align-items: center;
    padding: 0;
    margin: 0;
    font-size: 14px;
  }
  
  .breadcrumb ol li {
    display: flex;
    align-items: center;
  }
  
  .breadcrumb ol li + li::before {
    content: '›';
    margin: 0 8px;
    color: #666666;
  }
  
  .breadcrumb ol li a {
    color: #000091;
    text-decoration: none;
  }
  
  .breadcrumb ol li a:hover {
    text-decoration: underline;
  }
  
  .breadcrumb ol li[aria-current="page"] {
    color: #666666;
  }
  
  
  /* ============================================================
     3. HERO
     Une bande photo, puis une carte blanche qui remonte dessus.
     ============================================================ */
  .hero {
    margin-bottom: 40px;
  }
  
  /* ---------- La bande photo ---------- */
  .hero__image {
    height: 300px;
    background-image:
      /* voile bleu pour garder la photo lisible */
      linear-gradient(180deg, rgba(0, 0, 145, 0.55) 0%, rgba(0, 0, 145, 0.25) 100%),
      url("/demenagement.jpg");
    background-size: cover;
    background-position: center 35%;
  }
  
  /* ---------- La carte blanche ---------- */
  .hero__card {
    position: relative;             /* passe au-dessus de la photo */
    margin: -120px 40px 0;          /* la remontée sur la photo */
    background-color: #ffffff;
    border-top: 4px solid #E1000F;  /* liseré Marianne */
    border-radius: 16px;
    padding: 32px 36px 30px;
    box-shadow: 0 12px 40px rgba(10, 10, 60, 0.16);
    animation: hero-apparition 0.6s ease both;
  }
  
  @keyframes hero-apparition {
    from { opacity: 0; transform: translateY(20px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  
  /* ---------- Textes du hero ---------- */
  .hero__label {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #000091;
    margin: 0 0 14px;
  }
  
  .hero__title {
    font-size: 32px;
    font-weight: 700;
    line-height: 1.2;
    color: #161616;
    margin: 0 0 14px;
  }
  
  /* Mots surlignés au marqueur bleu clair */
  .hero__title span {
    color: #000091;
    background: linear-gradient(transparent 62%, #CACAFB 62%);
    padding: 0 4px;
  }
  
  .hero__text {
    font-size: 16px;
    line-height: 1.65;
    color: #666666;
    max-width: 680px;
    margin: 0 0 28px;
  }
  
  .hero__text strong {
    font-weight: 700;
    color: #161616;
  }
  
  /* ---------- Boutons du hero ---------- */
  .hero__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    align-items: center;
  }
  
  .btn-primary {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background-color: #000091;
    color: #ffffff;
    border: none;
    border-radius: 8px;
    padding: 13px 24px;
    font-family: 'Marianne', Arial, sans-serif;
    font-size: 16px;
    font-weight: 700;
    text-decoration: none;
    cursor: pointer;
    transition: background-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
  }
  
  .btn-primary:hover {
    background-color: #1212FF;
    color: #ffffff;
    text-decoration: none;
    transform: translateY(-2px);
    box-shadow: 0 10px 22px rgba(0, 0, 145, 0.26);
  }
  
  .btn-primary svg {
    width: 15px;
    height: 15px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: transform 0.2s ease;
  }
  
  /* La flèche avance au survol */
  .btn-primary:hover svg {
    transform: translateX(4px);
  }
  
  .btn-secondary {
    display: inline-flex;
    align-items: center;
    background-color: #ffffff;
    color: #000091;
    border: 1px solid #000091;
    border-radius: 8px;
    padding: 13px 24px;
    font-family: 'Marianne', Arial, sans-serif;
    font-size: 16px;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
    transition: background-color 0.2s ease, transform 0.2s ease;
  }
  
  .btn-secondary:hover {
    background-color: #F5F5FE;
    color: #000091;
    text-decoration: none;
    transform: translateY(-2px);
  }
  
  
  /* ============================================================
     4. BLOC SIMULATEUR
     Carte d'appel vers le simulateur CIMob.
     ============================================================ */
  .sim-intro {
    background-color: #ffffff;
    border-radius: 20px;
    box-shadow: 0 2px 18px rgba(10, 10, 60, 0.06);
    max-width: 800px;
    margin: 0 auto 48px;
    padding: 48px 40px 40px;
    text-align: center;
  }
  
  /* ---------- Le trajet avec l'avion ---------- */
  .sim-route {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 340px;
    height: 30px;
    margin: 0 auto 32px;
  }
  
  .sim-route__dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background-color: #000091;
    flex-shrink: 0;
  }
  
  .sim-route__dot--end {
    background-color: #ffffff;
    border: 2px solid #000091;
  }
  
  .sim-route__line {
    position: absolute;
    left: 18px;
    right: 18px;
    top: 50%;
    border-top: 2px dashed #DDDDDD;
  }
  
  /* L'avion traverse la ligne en boucle */
  .sim-route__plane {
    position: absolute;
    top: 50%;
    left: 0;
    width: 24px;
    height: 24px;
    color: #000091;
    /* rotate(90deg) : le dessin pointe vers le haut, on le met à plat */
    transform: translate(-50%, -50%) rotate(90deg);
    animation: sim-vol 7s ease-in-out infinite;
  }
  
  .sim-route__plane svg {
    width: 100%;
    height: 100%;
    fill: currentColor;
  }
  
  @keyframes sim-vol {
    0%   { left: 6%;  opacity: 0; }
    8%   { opacity: 1; }
    86%  { left: 94%; opacity: 1; }
    95%  { left: 94%; opacity: 0; }
    100% { left: 6%;  opacity: 0; }
  }
  
  /* ---------- Textes du bloc simulateur ---------- */
  .sim-kicker {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #000091;
    margin: 0 0 12px;
  }
  
  .sim-title {
    font-size: 32px;
    font-weight: 700;
    line-height: 1.2;
    color: #161616;
    margin: 0 0 16px;
  }
  
  .sim-title span {
    color: #000091;
    background: linear-gradient(transparent 62%, #CACAFB 62%);
    padding: 0 4px;
  }
  
  .sim-text {
    font-size: 16px;
    line-height: 1.6;
    color: #666666;
    max-width: 520px;
    margin: 0 auto 32px;
  }
  
  /* ---------- Les 3 familles d'offres ---------- */
  .sim-cards {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin: 0 0 32px;
  }
  
  .sim-card {
    background-color: #FAFAFA;
    border: 1px solid #EEEEEE;
    border-radius: 12px;
    padding: 20px 16px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }
  
  .sim-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 10px 22px rgba(0, 0, 0, 0.08);
  }
  
  .sim-card__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 10px;
    margin-bottom: 12px;
  }
  
  .sim-card__icon svg {
    width: 22px;
    height: 22px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  
  /* Une couleur par famille */
  .sim-card__icon--vert { background-color: #DFFDF0; color: #00A95F; }
  .sim-card__icon--bleu { background-color: #E8EDFF; color: #0063CB; }
  .sim-card__icon--rose { background-color: #FEE7FC; color: #6E445A; }
  
  .sim-card__title {
    font-size: 16px;
    font-weight: 700;
    color: #161616;
    margin: 0 0 4px;
  }
  
  .sim-card__text {
    font-size: 14px;
    line-height: 1.45;
    color: #666666;
    margin: 0;
  }
  
  /* ---------- Bouton du simulateur ---------- */
  .sim-button {
    font-family: 'Marianne', Arial, sans-serif;
    font-size: 16px;
    font-weight: 700;
    color: #ffffff;
    background-color: #000091;
    border: none;
    border-radius: 8px;
    padding: 14px 32px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    transition: background-color 0.2s ease, transform 0.2s ease;
  }
  
  .sim-button:hover {
    background-color: #1212FF;
    transform: translateY(-2px);
  }
  
  .sim-button svg {
    width: 16px;
    height: 16px;
    fill: none;
    stroke: #ffffff;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: transform 0.2s ease;
  }
  
  .sim-button:hover svg {
    transform: translateX(4px);
  }
  
  .sim-hint {
    font-size: 13px;
    color: #666666;
    margin: 16px 0 0;
  }
  
  
  /* ============================================================
     5. ACTUALITÉS
     Une actualité à la une à gauche, trois brèves à droite.
     ============================================================ */
  .news {
    padding: 0 0 48px;
  }
  
  /* ---------- Titre de section ---------- */
  .news__head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
    flex-wrap: wrap;
    margin-bottom: 28px;
  }
  
  .news__label {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #000091;
    margin: 0 0 8px;
  }
  
  .news__title {
    font-size: 26px;
    font-weight: 700;
    color: #161616;
    margin: 0;
  }
  
  .news__title span {
    color: #000091;
    background: linear-gradient(transparent 62%, #CACAFB 62%);
    padding: 0 4px;
  }
  
  /* Lien "Voir tout" */
  .news__all {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    font-weight: 700;
    color: #000091;
    text-decoration: none;
    white-space: nowrap;
    transition: gap 0.2s ease;
  }
  
  .news__all:hover {
    gap: 13px;
    color: #000091;
    text-decoration: underline;
  }
  
  .news__all svg {
    width: 17px;
    height: 17px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
  }
  
  /* ---------- Disposition ---------- */
  .news__grid {
    display: grid;
    grid-template-columns: 1.25fr 1fr;
    gap: 24px;
  }
  
  .news__side {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  
  /* ---------- Actualité à la une ---------- */
  .news-main {
    display: block;
    border: 1px solid #E5E5E5;
    border-radius: 14px;
    overflow: hidden;
    text-decoration: none;
    color: inherit;
    transition: transform 0.3s cubic-bezier(0.33, 1, 0.68, 1),
                box-shadow 0.3s ease;
  }
  
  .news-main:hover {
    transform: translateY(-3px);
    box-shadow: 0 12px 30px rgba(10, 10, 60, 0.12);
    color: inherit;
    text-decoration: none;
  }
  
  .news-main__image {
    height: 220px;
    background-image: url("/x_snc_habitat.logement.png");
    background-size: cover;
    background-position: center;
    transition: transform 0.5s cubic-bezier(0.33, 1, 0.68, 1);
  }
  
  /* L'image zoome légèrement au survol */
  .news-main:hover .news-main__image {
    transform: scale(1.05);
  }
  
  .news-main__body {
    padding: 20px 22px 22px;
  }
  
  .news-main__headline {
    font-size: 19px;
    font-weight: 700;
    line-height: 1.35;
    color: #161616;
    margin: 12px 0 8px;
  }
  
  .news-main__text {
    font-size: 14px;
    line-height: 1.6;
    color: #666666;
    margin: 0 0 12px;
  }
  
  /* ---------- Brèves ---------- */
  .news-item {
    display: flex;
    gap: 14px;
    align-items: center;
    background-color: #FAFAFA;
    border: 1px solid #EEEEEE;
    border-radius: 12px;
    padding: 12px;
    text-decoration: none;
    color: inherit;
    transition: transform 0.3s cubic-bezier(0.33, 1, 0.68, 1),
                background-color 0.3s ease,
                border-color 0.3s ease,
                box-shadow 0.3s ease;
  }
  
  .news-item:hover {
    transform: translateX(3px);
    background-color: #ffffff;
    border-color: #CACAFB;
    box-shadow: 0 4px 16px rgba(10, 10, 60, 0.06);
    color: inherit;
    text-decoration: none;
  }
  
  .news-item__image {
    width: 88px;
    height: 88px;
    flex-shrink: 0;
    border-radius: 10px;
    background-image: url("/x_snc_habitat.demarche.png");
    background-size: cover;
    background-position: center;
  }
  
  .news-item__body {
    min-width: 0;
  }
  
  .news-item__headline {
    font-size: 14.5px;
    font-weight: 700;
    line-height: 1.4;
    color: #161616;
    margin: 6px 0;
  }
  
  /* ---------- Éléments communs ---------- */
  .news-tag {
    display: inline-block;
    background-color: #F5F5FE;
    color: #000091;
    font-size: 11px;
    font-weight: 700;
    padding: 4px 10px;
    border-radius: 999px;
  }
  
  .news-date {
    font-size: 12px;
    color: #666666;
  }
  
  
  /* ============================================================
     6. FAQ
     Les questions s'accrochent en alternance à une courbe rouge.
     L'accordéon utilise <details> : aucun JavaScript nécessaire.
     ============================================================ */
  .faq {
    padding: 0 0 48px;
  }
  
  /* ---------- Titre de section ---------- */
  .faq__head {
    text-align: center;
    margin-bottom: 44px;
  }
  
  .faq__label {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: #000091;
    margin: 0 0 10px;
  }
  
  .faq__title {
    font-size: 28px;
    font-weight: 700;
    color: #161616;
    margin: 0 0 10px;
  }
  
  .faq__title span {
    color: #000091;
    background: linear-gradient(transparent 62%, #CACAFB 62%);
    padding: 0 4px;
  }
  
  .faq__text {
    font-size: 15px;
    color: #666666;
    max-width: 520px;
    margin: 0 auto;
  }
  
  /* ---------- La zone du chemin ---------- */
  .faq__path-wrap {
    position: relative;
  }
  
  /* Le chemin rouge : il se dessine au chargement */
  .faq__path {
    position: absolute;
    left: 50%;
    top: 0;
    /* il s'étire sur toute la hauteur du bloc de questions, donc il
       s'arrête net avant le bouton "Voir toutes les questions" */
    height: 100%;
    width: 420px;
    transform: translateX(-50%);
    z-index: 0;
    pointer-events: none;
  }
  
    .faq__path-trait {
    stroke: #E1000F;
    stroke-width: 3;
    fill: none;
    stroke-dasharray: 8 10;
    stroke-linecap: round;
  }

  .faq__path-masque {
    stroke-dasharray: 810;
    stroke-dashoffset: 810;
  }

  .faq.is-visible .faq__path-masque {
    animation: faq-trace 4.5s cubic-bezier(0.33, 0, 0.15, 1) 0.3s forwards;
  }
  
  @keyframes faq-trace {
    to { stroke-dashoffset: 0; }
  }
  
  /* ---------- Les illustrations ---------- */
  .faq__illu {
    position: absolute;
    z-index: 0;
    opacity: 0.9;
  }
  
  .faq__illu svg {
    width: 150px;
    height: auto;
  }
  
  .faq__illu--1 { right: 2%; top: 20px; }
  .faq__illu--2 { left: 1%; top: 330px; }
  
  /* ---------- Une question ---------- */
  .faq__item {
    position: relative;
    z-index: 1;
    width: 62%;
    margin-bottom: 26px;
    /* invisible tant que la section n'est pas repérée par le JS */
    opacity: 0;
  }
  
  /* Les questions paires sont décalées vers la droite */
  .faq__item:nth-child(even) {
    margin-left: 38%;
  }
  
  /* L'apparition en cascade ne démarre que lorsque .faq porte la classe
     "is-visible" (ajoutée par le JS au moment où la section entre dans
     l'écran). Les questions impaires entrent par la gauche, les paires
     par la droite. Les 2 illustrations occupant les 2 premières positions,
     les questions commencent au 4e enfant. */
  .faq.is-visible .faq__item:nth-child(odd)  { animation: faq-entree-gauche 0.7s cubic-bezier(0.22, 0.7, 0.3, 1) forwards; }
  .faq.is-visible .faq__item:nth-child(even) { animation: faq-entree-droite 0.7s cubic-bezier(0.22, 0.7, 0.3, 1) forwards; }
  
  .faq__item:nth-child(4) { animation-delay: 0.30s; }
  .faq__item:nth-child(5) { animation-delay: 0.55s; }
  .faq__item:nth-child(6) { animation-delay: 0.80s; }
  .faq__item:nth-child(7) { animation-delay: 1.05s; }
  .faq__item:nth-child(8) { animation-delay: 1.30s; }
  
  @keyframes faq-entree-gauche {
    from { opacity: 0; transform: translateX(-34px); }
    to   { opacity: 1; transform: translateX(0); }
  }
  
  @keyframes faq-entree-droite {
    from { opacity: 0; transform: translateX(34px); }
    to   { opacity: 1; transform: translateX(0); }
  }
  
  /* ---------- La carte ---------- */
  .faq-q {
    background-color: #ffffff;
    border: 1px solid #E5E5E5;
    border-radius: 14px;
    transition: border-color 0.3s ease, box-shadow 0.3s ease;
  }
  
  .faq-q:hover {
    border-color: #CACAFB;
    box-shadow: 0 4px 16px rgba(10, 10, 60, 0.06);
  }
  
  .faq-q[open] {
    border-color: #CACAFB;
    box-shadow: 0 8px 24px rgba(10, 10, 60, 0.09);
  }
  
  /* ---------- La ligne cliquable ---------- */
  .faq-q__btn {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 18px 20px;
    font-size: 15.5px;
    font-weight: 700;
    color: #161616;
    cursor: pointer;
    /* on masque la flèche par défaut de <details> */
    list-style: none;
  }
  
  .faq-q__btn::-webkit-details-marker {
    display: none;
  }
  
  /* Le numéro de la question */
  .faq-q__num {
    flex-shrink: 0;
    width: 30px;
    height: 30px;
    border-radius: 9px;
    background-color: #F5F5FE;
    color: #000091;
    font-size: 13px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background-color 0.3s ease, color 0.3s ease, transform 0.3s ease;
  }
  
  .faq-q[open] .faq-q__num {
    background-color: #000091;
    color: #ffffff;
    transform: scale(1.06);
  }
  
  .faq-q__txt {
    flex: 1;
  }
  
  /* ---------- Le + qui devient − ---------- */
  .faq-q__sign {
    flex-shrink: 0;
    position: relative;
    width: 18px;
    height: 18px;
  }
  
  .faq-q__sign::before,
  .faq-q__sign::after {
    content: "";
    position: absolute;
    background-color: #000091;
    border-radius: 2px;
    transition: transform 0.35s cubic-bezier(0.22, 0.7, 0.3, 1), opacity 0.35s ease;
  }
  
  /* La barre horizontale */
  .faq-q__sign::before {
    top: 8px;
    left: 0;
    width: 18px;
    height: 2px;
  }
  
  /* La barre verticale : elle pivote et disparaît à l'ouverture */
  .faq-q__sign::after {
    left: 8px;
    top: 0;
    width: 2px;
    height: 18px;
  }
  
  .faq-q[open] .faq-q__sign::after {
    transform: rotate(90deg);
    opacity: 0;
  }
  
  /* ---------- La réponse ---------- */
  .faq-q__answer {
    padding: 0 20px 20px 64px;
    font-size: 14.5px;
    line-height: 1.7;
    color: #666666;
  }
  
  /* Le texte monte en fondu à l'ouverture */
  .faq-q[open] .faq-q__answer {
    animation: faq-ouverture 0.4s ease both;
  }
  
  @keyframes faq-ouverture {
    from { opacity: 0; transform: translateY(-8px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  
  /* ---------- Voir toutes les questions ---------- */
  .faq__more {
    /* passe au-dessus du chemin, dont le tracé se termine juste derrière */
    position: relative;
    z-index: 1;
    display: flex;
    justify-content: center;
    margin-top: 36px;
  }
  
  .faq__more-link {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background-color: #ffffff;
    color: #000091;
    border: 1px solid #000091;
    border-radius: 8px;
    padding: 13px 26px;
    font-family: 'Marianne', Arial, sans-serif;
    font-size: 15px;
    font-weight: 700;
    text-decoration: none;
    transition: background-color 0.2s ease, transform 0.2s ease;
  }
  
  .faq__more-link:hover {
    background-color: #F5F5FE;
    color: #000091;
    text-decoration: none;
    transform: translateY(-2px);
  }
  
  .faq__more-link svg {
    width: 16px;
    height: 16px;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
    transition: transform 0.2s ease;
  }
  
  .faq__more-link:hover svg {
    transform: translateX(4px);
  }
  
  
  /* ============================================================
     7. INFORMATIONS PRATIQUES
     Version provisoire : le front sera revu.
     ============================================================ */
  .infos {
    padding: 0 0 56px;
  }
  
  .infos__head {
    margin-bottom: 24px;
  }
  
  .infos__title {
    font-size: 26px;
    font-weight: 700;
    color: #161616;
    margin: 0;
  }
  
  .infos__title span {
    color: #000091;
    background: linear-gradient(transparent 62%, #CACAFB 62%);
    padding: 0 4px;
  }
  
  .infos__grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }
  
  .infos-tile {
    display: flex;
    align-items: center;
    gap: 12px;
    background-color: #FAFAFA;
    border: 1px solid #EEEEEE;
    border-radius: 12px;
    padding: 14px 16px;
    text-decoration: none;
    color: #161616;
    font-size: 14px;
    font-weight: 600;
    line-height: 1.4;
    transition: border-color 0.2s ease, background-color 0.2s ease,
                transform 0.2s ease, box-shadow 0.2s ease;
  }
  
  .infos-tile:hover {
    border-color: #CACAFB;
    background-color: #ffffff;
    color: #000091;
    text-decoration: none;
    transform: translateX(3px);
    box-shadow: 0 4px 12px rgba(10, 10, 60, 0.06);
  }
  
  .infos-tile svg {
    width: 20px;
    height: 20px;
    fill: none;
    stroke: #000091;
    stroke-width: 1.9;
    stroke-linecap: round;
    stroke-linejoin: round;
    flex-shrink: 0;
  }
  
  .infos-tile__arrow {
    margin-left: auto;
    width: 16px;
    height: 16px;
    stroke-width: 2;
    transition: transform 0.2s ease;
  }
  
  .infos-tile:hover .infos-tile__arrow {
    transform: translateX(4px);
  }
  
  
  /* ============================================================
     8. DIVERS
     ============================================================ */
  .separator {
    border: none;
    border-top: 1px solid #E5E5E5;
    margin: 0 0 40px;
  }
  
  
  /* ============================================================
     MOBILE
     ============================================================ */
  @media (max-width: 768px) {
  
    /* Hero */
    .hero__image { height: 200px; }
    .hero__card  { margin: -80px 16px 0; padding: 24px 20px; }
    .hero__title { font-size: 24px; }
  
    .btn-primary,
    .btn-secondary {
      width: 100%;
      justify-content: center;
    }
  
    /* Simulateur */
    .sim-intro { padding: 32px 20px 28px; }
    .sim-title { font-size: 24px; }
    .sim-cards { grid-template-columns: 1fr; }
  
    /* Actualités */
    .news__grid        { grid-template-columns: 1fr; }
    .news-main__image  { height: 180px; }
    .news-item__image  { width: 72px; height: 72px; }
  
    /* FAQ : le chemin et les illustrations n'ont plus de place */
    .faq__path,
    .faq__illu { display: none; }
  
    .faq__item,
    .faq__item:nth-child(even) {
      width: 100%;
      margin-left: 0;
    }
  
    /* Arrivée par le bas plutôt que par les côtés */
    .faq.is-visible .faq__item:nth-child(odd),
    .faq.is-visible .faq__item:nth-child(even) {
      animation-name: faq-entree-bas;
    }
  
    .faq-q__answer { padding-left: 20px; }
  
    /* Informations pratiques */
    .infos__grid { grid-template-columns: 1fr; }
  }
  
  
  /* Arrivée verticale, utilisée sur mobile */
  @keyframes faq-entree-bas {
    from { opacity: 0; transform: translateY(24px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  
  
  /* ============================================================
     ACCESSIBILITÉ
     Animations coupées si l'utilisateur le demande (RGAA).
     Limité au widget : on ne cible jamais * seul.
     ============================================================ */
  @media (prefers-reduced-motion: reduce) {
    .accueil-familles *,
    .accueil-familles *::before,
    .accueil-familles *::after {
      animation: none !important;
      transition: none !important;
    }
  
    /* les questions doivent rester visibles sans leur animation */
    .faq__item { opacity: 1; }
  
    /* le chemin s'affiche tracé d'emblée */
    .faq__path-masque { stroke-dashoffset: 0; }
   
  }

/* ============================================================
   INFORMATIONS PRATIQUES
   1. Titre de section
   2. Carte de recherche du bureau logement
   3. Liste des rubriques
   4. Mobile
   5. Accessibilite
   ============================================================ */


/* ============================================================
   1. TITRE DE SECTION
   ============================================================ */
.infos {
  padding: 0 0 56px;
}

.infos__title {
  font-size: 26px;
  font-weight: 700;
  color: #161616;
  margin: 0 0 26px;
}

/* Le mot surligne au marqueur bleu */
.infos__title span {
  color: #000091;
  background: linear-gradient(transparent 62%, #CACAFB 62%);
  padding: 0 4px;
}


/* ============================================================
   2. CARTE DE RECHERCHE
   Le texte a gauche, l'image a droite.
   ============================================================ */
.infos-recherche {
  display: grid;
  grid-template-columns: 1fr 330px;
  border: 1px solid #E5E5E5;
  border-radius: 16px;
  overflow: hidden;
  background-color: #ffffff;
  margin-bottom: 20px;
}

.infos-recherche__body {
  padding: 32px 34px;
}

.infos-recherche__titre {
  font-size: 18px;
  font-weight: 700;
  color: #161616;
  margin: 0 0 8px;
}

.infos-recherche__texte {
  font-size: 14px;
  line-height: 1.6;
  color: #666666;
  margin: 0;
}

/* ---------- L'image ---------- */
.infos-recherche__image {
  min-height: 200px;
  background-image: url("/rechercheBase.png");
  background-size: cover;
  background-position: center;
}

/* ---------- Le formulaire ---------- */
.infos-recherche__form {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 20px;
}

/* Le label est masque a l'ecran mais lu par les lecteurs d'ecran */
.infos-recherche__label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.infos-recherche__select {
  font-family: 'Marianne', Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: #161616;
  background-color: #ffffff;
  border: 1px solid #E5E5E5;
  border-radius: 10px;
  padding: 11px 16px;
  min-width: 230px;
  cursor: pointer;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.infos-recherche__select:hover {
  border-color: #CACAFB;
  box-shadow: 0 4px 14px rgba(10, 10, 60, 0.06);
}

.infos-recherche__bouton {
  font-family: 'Marianne', Arial, sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: #ffffff;
  background-color: #000091;
  border: none;
  border-radius: 10px;
  padding: 11px 22px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background-color 0.2s ease, transform 0.2s ease;
}

.infos-recherche__bouton:hover {
  background-color: #1212FF;
  transform: translateY(-2px);
}

.infos-recherche__bouton svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: #ffffff;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 0.2s ease;
}

/* La fleche avance au survol */
.infos-recherche__bouton:hover svg {
  transform: translateX(3px);
}


/* ============================================================
   3. LISTE DES RUBRIQUES
   Pas de cartes : de simples lignes separees par un filet.
   ============================================================ */
.infos-liste {
  border-top: 1px solid #EDEDF2;
}

.infos-ligne {
  position: relative;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 24px 16px;
  border-bottom: 1px solid #EDEDF2;
  text-decoration: none;
  color: inherit;
  transition: padding-left 0.35s cubic-bezier(0.33, 1, 0.68, 1),
              background-color 0.35s ease;
}

/* Un liseré bleu se deploie a gauche au survol */
.infos-ligne::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background-color: #000091;
  transform: scaleY(0);
  transition: transform 0.35s cubic-bezier(0.33, 1, 0.68, 1);
}

.infos-ligne:hover {
  background-color: #FBFBFE;
  padding-left: 26px;
  color: inherit;
  text-decoration: none;
}

.infos-ligne:hover::before {
  transform: scaleY(1);
}

/* ---------- L'illustration ---------- */
.infos-ligne__illu {
  flex-shrink: 0;
  width: 64px;
  height: 64px;
  transition: transform 0.4s cubic-bezier(0.33, 1, 0.68, 1);
}

.infos-ligne:hover .infos-ligne__illu {
  transform: scale(1.1) rotate(-3deg);
}

.infos-ligne__illu svg {
  width: 100%;
  height: 100%;
}

/* ---------- Les textes ---------- */
.infos-ligne__body {
  flex: 1;
  min-width: 0;
}

.infos-ligne__titre {
  display: block;
  font-size: 16.5px;
  font-weight: 700;
  color: #161616;
  line-height: 1.3;
  margin-bottom: 6px;
}

.infos-ligne__texte {
  display: block;
  font-size: 13.5px;
  line-height: 1.6;
  color: #666666;
}

/* ---------- Le lien, revele au survol ---------- */
.infos-ligne__lien {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13.5px;
  font-weight: 700;
  color: #000091;
  opacity: 0;
  transform: translateX(-8px);
  transition: opacity 0.35s ease, transform 0.35s ease;
}

.infos-ligne:hover .infos-ligne__lien {
  opacity: 1;
  transform: translateX(0);
}

.infos-ligne__lien svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}


/* ============================================================
   4. MOBILE
   ============================================================ */
@media (max-width: 768px) {

  .infos-recherche {
    grid-template-columns: 1fr;
  }

  /* L'image passe au-dessus du texte */
  .infos-recherche__image {
    order: -1;
    min-height: 150px;
  }

  .infos-recherche__body {
    padding: 24px 20px;
  }

  .infos-recherche__select,
  .infos-recherche__bouton {
    width: 100%;
    justify-content: center;
  }

  /* Le lien reste toujours visible, faute de survol au doigt */
  .infos-ligne__lien {
    display: none;
  }

  .infos-ligne {
    gap: 16px;
    padding: 20px 12px;
  }

  .infos-ligne__illu {
    width: 52px;
    height: 52px;
  }
}


/* ============================================================
   5. ACCESSIBILITE
   Animations coupees si l'utilisateur le demande.
   ============================================================ */
@media (prefers-reduced-motion: reduce) {

  .infos-ligne,
  .infos-ligne__illu,
  .infos-ligne__lien,
  .infos-recherche__bouton,
  .infos-recherche__select {
    transition: none;
  }

  /* Le lien reste visible sans son animation */
  .infos-ligne__lien {
    opacity: 1;
    transform: none;
  }
}
